Here's the complete, self-contained double pendulum simulation:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Double Pendulum</title>
  <style>
    :root {
      --bg:        #0e1118;
      --surface:   #161c2a;
      --border:    #29344f;
      --text:      #cdd5e0;
      --muted:     #6b7a99;
      --accent:    #5bc8f5;
      --accent-dk: #3a8fb5;
    }
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: ar(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, sans-serif;
      font-size: 14px;
      line-height: 1.5;
      display: flex;
      flex-direction: column;
      align-items: center;
      min-height: 100vh;
      padding: 24px 16px;
      gap: 16px;
    }

    h1 { font-size: 1.05rem; font-weight: 600; letter-spacing: 0.04em; }

    canvas {
      display: block;
      border: 1px solid var(--border);
      border-radius: 8px;
      background: var(--surface);
      max-width: 100%;
    }

    .controls {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      justify-content: center;
    }

    button {
      background: var(--surface);
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 8px 18px;
      font-size: 13px;
      cursor: pointer;
      min-height: 44px;
      transition: background 120ms ease, border-color 120ms ease;
    }
    button:hover        { background: #1d2538; border-color: var(--accent-dk); }
    button:active       { background: #232d48; }visible{ outline: 2px solid var(--accent); outline-offset: 2px; }
    button.primary      { border-color: var(--accent-dk); color: var(--accent); }

    .params {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(155px, 1fr));
      gap: 8px 16px;
      width: 100%;
      max-width: 560px;
    }

    label {
      display: flex;
      flex-direction: column;
      gap: 3px;
      color: var(--muted);
      font-size: 12px;
    }

    input[type="range"] { accent-color: var(--accent); width: 100%; cursor: pointer; }
    .val { color: var(--text); font-variant-numeric: tabular-nums; }
    .note { color: var(--muted); font-size: 12px; text-align: center; }
  </style>
</head>
<body>
  <h1>Double Pendulum — RK4 Integration</h1>

  <canvas id="c" width="560" height="520"
          aria-label="Animated double pendulum with motion trail"></canvas>

  <div class="controls">
    <button id="btnPause" class="primary">Pause</button>
    <button id="btnReset">Reset</button>
    <button id="btnClear">Clear Trail</button>
  </div>

  <div class="params">
    <label>θ₁ initial: <span class="val" id="vT1">120</span>°
      <input type="range" min="-180" max="180" value="120"></label>

    <label>θ₂ initial: <span class="val" id="vT2">-20</span>°
      <input type="range" id="sT2" min="-180" max="180" value="-20"></label>

    <label>m₁: <span class="val" id="vM1">1.0</span>
      <input type="range" id="sM1" min="0.2" max="3" step="0.1" value="1.0"></label>

    <label>m₂: <span class="val" id="vM2">1.0</span>
      <input type="range" id="sM2" min="0.2" max="3" step="0.1" value="1.0"></label>

    <label>Trail length: <span class="val" id="vTR">600</span>
      <input type="range" id="sTR" min="50" max="2000" step="50" value="600"></label>

    <label>Speed: <span class="val" id="vSP">1.0</span>×
      <input type="range" id="sSP" min="0.1" max="4" step="0.1" value="1.0"></label>
  </div>

  <p class="note">Chaotic motion — a fraction of a degree in θ₁ produces a completely different trajectory.</p>

<script>
(() => {
  'use strict';

  const canvas = document.getElementById('c');
  const ctx    = canvas.getContext('2d');

  // Physical constants (SI uni lengths stand in for metres)
  const G  = 9.81;
  const L1 = 130;   // first rod length in px
  const L2 = 110;   // second rod length in px

  // Canvas origin (pivot point)
  const OX = canvas.width  / 2;
  const OY = canvas.height * 0.36;

  // Mutable simulation state
  let m1, m2;
  let theta1, omega1, theta2, omega2;
  let trail    = [];
  let maxTrail = 600;
  let paused   = false;
  let speed    = 1.0;
  let prevTime = null;

  // ── Lagrangian equations of motion ──────────────────────────────────────
  //
  // Derived from the Euler-Lagrange equations for a double pendulum with
  // point masses m1, m2 on massless rigid rods L1, L2 in uniform gravity g.
  //
  // The Lagrangian is:
  //   T = ½(m1+m2)L1²ω1² + ½m2L2²ω2² + m2 L1 L2 ω1 ω2 cos(θ1−θ2)
  //   V = −(m1+m2)g L1 cos θ1 − m2 g L2 cos θ2
  //   L = T − V
  //
  // Solving the resulting coupled ODEs for α1 and α2 gives the closed forms
  // below (standard result; see e.g. Meirovitch, "Methods of Analytical Dynamics").
  //
  // Returns state derivative: [dθ1/dt, dω1/dt, dθ2/dt, dω2/dt]
  function deriv(t1, w1, t2, w2) {
    const d  = t1 - t2;
    const sd = Math.sin(d);
    const cd = Math.cos(d);
    // Shared denominator: L1·(2m1 + m2 − m2·cos(2Δ))
    const D  = 2*m1 + m2 - m2 * Math.cos(2 * d);

    const a1 = (
      -G * (2*m1 + m2) * Math.sin(t1)
      - m2 * G * Math.sin(t1 - 2*t2)
      - 2*sd * m2 * (w2*w2*L2 + w1*w1*L1*cd)
    ) / (L1 * D);

    const a2 = (
      2 * sd * (
        w1*w1 * L1 * (m1 + m2)
        + G  * (m1 + m2) * Math.cos(t1)
        + w2*w2 * L2 * m2 * cd
      )
    ) / (L2 * D);

    return [w1, a1, w2, a2];
  }

  // ── Classical 4th-order Runge-Kutta ─────────────────────────────────────
  function rk4(t1, w1, t2, w2, h) {
    const k1 = deriv(t1,           w1,           t2,           w2);
    const k2 = deriv(t1+h/2*k1[0], w1+h/2*k1[1], t2+h/2*k1[2], w2+h/2*k1[3]);
    const k3 = deriv(t1+h/2*k2[0], w1+h/2*k2[1], t2+h/2*k2[2], w2+h/2*k2[3]);
    const k4 = deriv(t1+h*k3[0],   w1+h*k3[1],   t2+h*k3[2],   w2+h*k3[3]);
    return [
      t1 + h/6*(k1[0]+2*k2[0]+2*k3[0]+k4[0]),
      w1 + h/6*(k1[1]+2*k2[1]+2*k3[1]+k4[1]),
      t2 + h/6*(k1[2]+2*k2[2]+2*k3[2]+k4[2]),
      w2 + h/6*(k1[3]+2*k2[3]+2*k3[3]+k4[3]),
    ];
  }

  // ── Geometry helpers ─────────────────────────────────────────────────────
  // Canvas y-axis points down, so the resting position (θ=0) is directly
  // below the pivot: x += L·sin θ,  y += L·cos θ.
  function posBob1() {
    return [OX + L1*Math.sin(theta1), OY + L1*Math.cos(theta1)];
  }
  function posBob2() {
    const [x1, y1] = posBob1();
    return [x1 + L2*Math.sin(theta2), y1 + L2*Math.cos(theta2)];
  }

  // ── Drawing ──────────────────────────────────────────────────────────────
  function drawTrail() {
    const n = trail.length;
    if (n < 2) return;
    for (let i = 1; i < n; i++) {
      const t = i / n;          // 0 = oldest point, 1 = newest
      const a = t * t;          // quadratic fade so the tail vanishes smoothly
      ctx.beginPath();
      ctx.strokeStyle = `rgba(148,103,245,${(a * 0.88).toFixed(3)})`;
      ctx.lineWidth   = 0.7 + 1.6 * t;
      ctx.lineCap     = 'round';
      ctx.moveTo(trail[i-1][0], trail[i-1][1]);
      ctx.lineTo(trail[i][0],   trail[i][1]);
      ctx.stroke();
    }
  }

  function drawRod(ax, ay, bx, by) {
    ctx.beginPath();
    ctx.strokeStyle = '#7a8aaa';
    ctx.lineWidth   = 2.5;
    ctx.lineCap     = 'round';
    ctx.moveTo(ax, ay);
    ctx.lineTo(bx, by);
    ctx.stroke();
  }

  function drawBob(x, y, r, color) {
    // soft glow behind the bob
    ctx.save();
    ctx.shadowColor = color;
    ctx.shadowBlur  = 18;
    ctx.fillStyle   = color;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    // specular highlight
    ctx.fillStyle = 'rgba(255,255,255,0.22)';
    ctx.beginPath();
    ctx.arc(x - r*0.28, y - r*0.28, r*0.38, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawPivot() {
    ctx.fillStyle   = '#c0c8d8';
    ctx.strokeStyle = '#5a6a88';
    ctx.lineWidth   = 1;
    ctx.beginPath();
    ctx.arc(OX, OY, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }

  function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawTrail();
    const [x1, y1] = posBob1();
    const [x2, y2] = posBob2();
    drawRod(OX, OY, x1, y1);
    drawRod(x1, y1, x2, y2);
    drawPivot();
    drawBob(x1, y1, 12, '#e87a4a');   // warm orange  — bob 1
    drawBob(x2, y2, 10, '#4dd898');   // seafoam green — bob 2
  }

  // ── Animation loop ───────────────────────────────────────────────────────
  const SUB_STEPS = 10;   // RK4 sub-steps per frame for energy conservation

  function tick(now) {
    if (!paused) {
      if (prevTime === null) prevTime = now;
      // Clamp Δt to 50 ms so a hidden tab doesn't cause a large jump on resume
      let dt = Math.min((now - prevTime) / 1000, 0.05) * speed;
      prevTime = now;

      const h = dt / SUB_STEPS;
      for (let i = 0; i < SUB_STEPS; i++) {
        [theta1, omega1, theta2, omega2] = rk4(theta1, omega1, theta2, omega2, h);
      }

      trail.push(posBob2());
      if (trail.length > maxTrail) trail.shift();
    } else {
      prevTime = now;   // keep timestamp fresh so resume doesn't jump
    }

    render();
    requestAnimationFrame(tick);
  }

  // ── State initialisation ─────────────────────────────────────────────────
  function readMasses() {
    m1 = parseFloat(document.getElementById('sM1').value);
    m2 = parseFloat(document.getElementById('sM2').value);
  }

  function reset() {
    readMasses();
    theta1 = parseFloat(document.getElementById('sT1').value) * Math.PI / 180;
    theta2 = parseFloat(document.getElementById('sT2').value) * Math.PI / 180;
    omega1 = omega2 = 0;
    trail    = [];
    prevTime = null;
  }

  // ── Control wiring ───────────────────────────────────────────────────────
  document.getElementById('btnPause').addEventListener('click', () => {
    paused = !paused;
    document.getElementById('btnPause').textContent = paused ? 'Resume' : 'Pause';
  });

  document.getElementById('btnReset').addEventListener('click', () => {
    paused = false;
    document.getElementById('btnPause').textContent = 'Pause';
    reset();
  });

  document.getElementById('btnClear').addEventListener('click', () => {
    trail = [];
  });

  function wire(sliderId, valId, decimals, cb) {
    const s = document.getElementById(sliderId);
    const v = document.getElementById(valId);
    s.addEventListener('input', () => {
      v.textContent = parseFloat(s.value).toFixed(decimals);
      cb();
    });
  }

  wire('sT1', 'vT1', 0, reset);
  wire('sT2', 'vT2', 0, reset);
  wire('sM1', 'vM1', 1, readMasses);
  wire('sM2', 'vM2', 1, readMasses);
  wire('sTR', 'vTR', 0, () => { maxTrail = parseInt(document.getElementById('sTR').value); });
  wire('sSP', 'vSP', 1, () => { speed   = parseFloat(document.getElementById('sSP').value); });

  reset();
  requestAnimationFrame(tick);
})();
</script>
</body>
</html>
```

**What's in here:**

Physics — the `deriv()` function implements the exact closed-form Euler-Lagrange equations for a double pendulum. The derivation starts from the Lagrangian `L = T − V`, applies the Euler-Lagrange operator to both generalised coordinates θ₁ and θ₂, then solves the resulting 2×2 linear system for α₁ and α₂. The denominator `D = 2m₁ + m₂ − m₂cos(2Δ)` is the same for both equations.

Integration — classical RK4 runs 10 sub-steps per animation frame (roughly 1.7 ms per sub-step at 60 fps). This keeps the total energy drift visibly small over many seconds without being computationally expensive.

Trail — drawn segment-by-segment with alpha and stroke width both fading quadratically from the oldest point to the newest, so the head is always bright and the tail dissolves naturally.

Controls — drag any slider and the simulation resets immediately to the new initial conditions; speed and trail length take effect live without a reset.
